qualified_questions.sparql_query:
PREFIX saref: <https://w3id.org/saref#>

SELECT ?definition
WHERE {
    saref:Service rdfs:isDefinedBy ?definition.
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?propertyUsage
WHERE {
    :hasMinValue rdfs:subPropertyOf ?propertyUsage .
}

