    geo:sfWithin rdfs:isDefinedBy ?definition
}

# Write your query here.
SELECT ?class ?role
WHERE {
    ?class rdf:type owl:Class.
    ?class ?role ?object.
}

PREFIX ssn: <http://www.w3.org/ns/ssn/>
SELECT ?definition
WHERE {
    ssn:Property rdfs:isDefinedBy ?definition.
}

SELECT ?property
WHERE {
    ?property rdfs:subClassOf ssn-system:SystemProperty .
    FILTER(?property IN (ssn-system:Latency, ssn-system:ResponseTime))
}

