SELECT ?property
WHERE {
    ?property rdfs:subPropertyOf ssn:hasProperty .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX : <http://iot.linkeddata.es/def/core#>

SELECT ?property ?domain ?range ?inverseProperty
WHERE {
    {
        :hasNeighbourhood rdf:type owl:FunctionalProperty ;
                          rdfs:domain ?domain ;
                          rdfs:range ?range ;
                          owl:inverseOf ?inverseProperty .
        BIND(:hasNeighbourhood AS ?property)
    }
    UNION
    {
        :isNeighbourhoodOf rdf:type owl:FunctionalProperty ;
                           rdfs:domain ?domain ;
                           rdfs:range ?range ;
                           owl:inverseOf ?inverseProperty .
        BIND(:isNeighbourhoodOf AS ?property)
    }
}
